auto func (auto value){  
    int product = 1;  
    for (int i = 0; i < std::size(value); ++i)  
        product *= value[i];  
    return product;  
}

auto func (auto value){  
    int product = 1;  
    for (const auto& v : value)  
        product *= v;  
    return product;  
}
